	@Test
	public void packedAggregateCanBeForcedForWitnessQuery() {
		String query = PREFIX + " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }";
		try (SailRepositoryConnection conn = repository.getConnection()) {
			Map<String, Long> reference = resultMap(conn, query, "false", null);
			System.setProperty(PACKED_PROPERTY, "true");
			SailTupleQuery packedQuery = prepare(conn, query, PACKED_STRATEGY);
			String plan = String.valueOf(packedQuery.explain(Explanation.Level.Executed));
			assertThat(plan).contains("nativeExecutionPath=" + PACKED_STRATEGY);
			assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
			assertThat(resultMap(conn, query, "true", PACKED_STRATEGY)).isEqualTo(reference);
			assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
		}
	}

	@ParameterizedTest
	@CsvSource({ "false,false", "false,true", "true,false", "true,true" })
	void groupedWitnessAttemptsPreserveHandComputedWholeBag(boolean negated, boolean distinct) {
		String query = "SELECT ?patient (COUNT(" + (distinct ? "DISTINCT " : "") + "?enc) AS ?c) WHERE { "
				+ "?patient a <" + EX + "Patient> . ?patient <" + EX + "hasEncounter> ?enc . FILTER "
				+ (negated ? "NOT " : "") + "EXISTS { ?enc <" + EX + "hasCondition> ?cond } } GROUP BY ?patient";
		// For i modulo 12, the two independently added condition sets cover these encounter counts.
		// EXISTS collapses two conditions on one encounter; COUNT and COUNT(DISTINCT) must agree here.
		int[] covered = { 1, 1, 2, 2, 2, 1, 2, 2, 2, 1, 1, 1 };
		List<String> expected = new ArrayList<>();
		for (int patient = 0; patient < PATIENTS; patient++) {
			int count = covered[patient % covered.length];
			expected.add(EX + "patient" + patient + "|" + (negated ? 3 - count : count));
		}
		expected.sort(String::compareTo);
		try (SailRepositoryConnection connection = repository.getConnection()) {
			System.setProperty(PACKED_PROPERTY, "false");
			assertThat(groupedWitnessBag(connection, query, null)).containsExactlyElementsOf(expected);
			System.setProperty(PACKED_PROPERTY, "true");
			for (int opening = 0; opening < 6; opening++) {
				assertThat(groupedWitnessBag(connection, query, PACKED_STRATEGY)).containsExactlyElementsOf(expected);
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
			}
		}
	}

	private static List<String> groupedWitnessBag(SailRepositoryConnection connection, String query,
			String forcedStrategy) {
		List<String> result = new ArrayList<>();
		for (BindingSet row : QueryResults.asList(prepare(connection, query, forcedStrategy).evaluate())) {
			assertThat(row.getBindingNames()).containsExactlyInAnyOrder("patient", "c");
			result.add(row.getValue("patient").stringValue() + "|" + ((Literal) row.getValue("c")).longValue());
		}
		result.sort(String::compareTo);
		return result;
	}

	private void assertParity(String query) {
		try (SailRepositoryConnection conn = repository.getConnection()) {
			// Keep the reference on ordinary adaptive dispatch; explicitly select packed for every packed-on
			// evaluation.
			Map<String, Long> reference = resultMap(conn, query, "false", null);
			for (int round = 0; round < 6; round++) {
				assertThat(resultMap(conn, query, "true", PACKED_STRATEGY))
						.as("packed-on result (round %d)", round)
						.isEqualTo(reference);
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get())
						.as("native semijoin probes still held after result close (round %d)", round)
						.isZero();
			}
		}
	}

	private static SailTupleQuery prepare(SailRepositoryConnection conn, String query, String forcedStrategy) {
		SailTupleQuery preparedQuery = (SailTupleQuery) conn.prepareTupleQuery(QueryLanguage.SPARQL, query);
		preparedQuery.setForcedLmdbExecutionStrategy(forcedStrategy);
		return preparedQuery;
	}

	private static Map<String, Long> resultMap(SailRepositoryConnection conn, String query, String packedEnabled,
			String forcedStrategy) {
		System.setProperty(PACKED_PROPERTY, packedEnabled);
		List<BindingSet> rows = QueryResults.asList(prepare(conn, query, forcedStrategy).evaluate());
		Map<String, Long> byKey = new TreeMap<>();
		for (BindingSet row : rows) {
			String key = row.hasBinding("patient") ? row.getValue("patient").stringValue() : "";
			byKey.put(key, ((Literal) row.getValue("c")).longValue());
		}
		return byKey;
	}

	@Test
	void originalValuesWitnessOwnersHaveIndependentMemoryAndHandBags() {
		List<String> queries = List.of(
				PREFIX + " FILTER EXISTS { ?enc <" + EX + "hasCondition> <" + EX + "cond_flagged> } }",
				PREFIX + " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }",
				PREFIX + " FILTER NOT EXISTS { ?enc <" + EX + "hasCondition> ?cond } }",
				PREFIX + " FILTER EXISTS { ?enc <" + EX + "hasCondition> ?cond } }");
		long[] handCounts = new long[4];
		for (int patient = 0; patient < PATIENTS; patient++) {
			boolean[] selected = new boolean[4];
			for (int encounter = 0; encounter < 3; encounter++) {
				int value = 50 + (patient + encounter) % 30;
				if (value != 50 && value != 60 && value != 70) {
					continue;
				}
				boolean flagged = (patient * 5 + encounter) % 4 == 0;
				boolean condition = (patient * 7 + encounter) % 3 == 0 || flagged;
				selected[0] |= flagged;
				selected[1] |= !condition;
				selected[2] |= !condition;
				selected[3] |= condition;
			}
			for (int gate = 0; gate < selected.length; gate++) {
				if (selected[gate]) {
					handCounts[gate]++;
				}
			}
		}
		SailRepository memory = independentWitnessMemory();
		try {
			try (SailRepositoryConnection oracle = memory.getConnection();
					SailRepositoryConnection nativeConnection = repository.getConnection()) {
				System.setProperty(PACKED_PROPERTY, "true");
				for (int gate = 0; gate < queries.size(); gate++) {
					String query = queries.get(gate);
					var independent = oracle.prepareTupleQuery(query);
					SailTupleQuery forced = prepare(nativeConnection, query, PACKED_STRATEGY);
					for (int round = 0; round < 3; round++) {
						List<BindingSet> expected = QueryResults.asList(independent.evaluate());
						assertThat(expected).singleElement().satisfies(row -> {
							assertThat(row.getBindingNames()).containsExactly("c");
						});
						assertThat(((Literal) expected.getFirst().getValue("c")).longValue())
								.isEqualTo(handCounts[gate]);
						assertThat(QueryResults.asList(forced.evaluate())).containsExactlyElementsOf(expected);
						assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
					}
					Explanation explanation = forced.explain(Explanation.Level.Telemetry);
					assertThat(String.valueOf(explanation))
							.contains("nativeExecutionPath=" + PACKED_STRATEGY)
							.contains("nativeOnePassPackedRegionsOpenedActual");
					assertThat(hasPositiveOnePassPackedOpens(explanation.toGenericPlanNode())).isTrue();
					assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
				}
			}
		} finally {
			memory.shutDown();
		}
	}

	@Test
	void packedAggregateOwnsIslandDispatchAndRestoresThePublicForceBoundary() {
		String query = PREFIX + " FILTER EXISTS { ?enc <" + EX + "hasCondition> ?cond } }";
		String rowQuery = "SELECT ?patient WHERE { ?patient a <" + EX + "Patient> }";
		SailRepository memory = independentWitnessMemory();
		try {
			try (SailRepositoryConnection oracle = memory.getConnection();
					SailRepositoryConnection nativeConnection = repository.getConnection()) {
				List<BindingSet> expected = QueryResults.asList(oracle.prepareTupleQuery(query).evaluate());
				assertThat(expected).singleElement().satisfies(row -> {
					assertThat(row.getBindingNames()).containsExactly("c");
					// For the 64 patients, the independent encounter/value/condition formulas select 13.
					assertThat(((Literal) row.getValue("c")).longValue()).isEqualTo(13L);
				});
				System.setProperty(PACKED_PROPERTY, "true");
				SailTupleQuery forced = prepare(nativeConnection, query, PACKED_STRATEGY);
				SailTupleQuery ineligible = prepare(nativeConnection, rowQuery, PACKED_STRATEGY);
				for (int round = 0; round < 3; round++) {
					assertThat(QueryResults.asList(forced.evaluate())).containsExactlyElementsOf(expected);
					assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
					assertThatThrownBy(() -> QueryResults.asList(ineligible.evaluate()))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining("'" + PACKED_STRATEGY + "'")
							.hasMessageContaining("row/join dispatch")
							.hasMessageContaining("never a candidate");
					try (var result = forced.evaluate()) {
						assertThat(result.hasNext()).isTrue();
					}
					assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
					assertThatThrownBy(() -> QueryResults.asList(ineligible.evaluate()))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessageContaining("'" + PACKED_STRATEGY + "'")
							.hasMessageContaining("row/join dispatch")
							.hasMessageContaining("never a candidate");
				}
				Explanation explanation = forced.explain(Explanation.Level.Telemetry);
				assertThat(String.valueOf(explanation)).contains("nativeExecutionPath=" + PACKED_STRATEGY);
				assertThat(hasPositiveOnePassPackedOpens(explanation.toGenericPlanNode())).isTrue();
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
				assertThatThrownBy(() -> QueryResults.asList(ineligible.evaluate()))
						.isInstanceOf(QueryEvaluationException.class)
						.hasMessageContaining("'" + PACKED_STRATEGY + "'")
						.hasMessageContaining("row/join dispatch")
						.hasMessageContaining("never a candidate");
			}
		} finally {
			memory.shutDown();
		}
	}

	@ParameterizedTest
	@CsvSource({ "true,364", "false,320" })
	void legacyOrderedValuesDuplicatesUndefMinusOptionalUnionAndExistsKeepTheWholeCountBag(
			boolean storedTermDatatype, long independentCount) {
		assertThat(repository.getValueFactory().createLiteral(50).getDatatype()).isEqualTo(XSD.INT);
		String fifty = storedTermDatatype ? "\"50\"^^<" + XSD.INT + ">" : "50";
		String fiftyOne = storedTermDatatype ? "\"51\"^^<" + XSD.INT + ">" : "51";
		String query = "SELECT (COUNT(*) AS ?n) (COUNT(DISTINCT ?patient) AS ?c) WHERE { "
				+ "{ VALUES ?value { " + fifty + " " + fifty + " UNDEF } MINUS { VALUES ?value { "
				+ fiftyOne + " } } } "
				+ "?patient a <" + EX + "Patient> . ?patient <" + EX + "hasEncounter> ?enc . "
				+ "?enc <" + EX + "hasObservation> ?obs . ?obs <" + EX + "value> ?value . "
				+ "OPTIONAL { { ?enc <" + EX + "hasCondition> ?condition } UNION "
				+ "{ ?enc <" + EX + "hasCondition> ?condition } } "
				+ "FILTER EXISTS { ?enc <" + EX + "hasObservation> ?obs } }";
		long handRows = 0L;
		for (int patient = 0; patient < PATIENTS; patient++) {
			for (int encounter = 0; encounter < 3; encounter++) {
				long prefixCopies = storedTermDatatype && (patient + encounter) % 30 == 0 ? 3L : 1L;
				long conditions = ((patient * 7 + encounter) % 3 == 0 ? 1L : 0L)
						+ ((patient * 5 + encounter) % 4 == 0 ? 1L : 0L);
				handRows += prefixCopies * (conditions == 0L ? 1L : 2L * conditions);
			}
		}
		assertThat(handRows).isEqualTo(independentCount);
		SailRepository memory = independentWitnessMemory();
		try {
			try (SailRepositoryConnection oracle = memory.getConnection();
					SailRepositoryConnection nativeConnection = repository.getConnection()) {
				System.setProperty(PACKED_PROPERTY, "true");
				var independent = oracle.prepareTupleQuery(query);
				SailTupleQuery ordinary = prepare(nativeConnection, query, null);
				SailTupleQuery forced = prepare(nativeConnection, query, PACKED_STRATEGY);
				for (int round = 0; round < 3; round++) {
					List<BindingSet> expected = QueryResults.asList(independent.evaluate());
					assertThat(expected).hasSize(1);
					assertThat(expected.getFirst().getBindingNames()).containsExactlyInAnyOrder("n", "c");
					assertThat(((Literal) expected.getFirst().getValue("n")).longValue()).isEqualTo(handRows);
					assertThat(((Literal) expected.getFirst().getValue("c")).longValue()).isEqualTo(PATIENTS);
					assertThat(QueryResults.asList(ordinary.evaluate())).containsExactlyElementsOf(expected);
					assertThatThrownBy(() -> QueryResults.asList(forced.evaluate()))
							.isInstanceOf(QueryEvaluationException.class)
							.hasMessage("LMDB execution strategy '" + PACKED_STRATEGY
									+ "' could not be forced at row/join dispatch: it was never a candidate for this query's "
									+ "shape at this decision point (its structural precondition was not met).");
					assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
				}
			}
		} finally {
			memory.shutDown();
		}
	}

	private static boolean hasPositiveOnePassPackedOpens(GenericPlanNode node) {
		Long opened = node.getLongMetricActual("nativeOnePassPackedRegionsOpenedActual");
		if (opened != null && opened > 0L) {
			return true;
		}
		List<GenericPlanNode> children = node.getPlans();
		if (children != null) {
			for (GenericPlanNode child : children) {
				if (hasPositiveOnePassPackedOpens(child)) {
					return true;
				}
			}
		}
		return false;
	}

	private static SailRepository independentWitnessMemory() {
		SailRepository memory = new SailRepository(new MemoryStore());
		try {
			try (SailRepositoryConnection connection = memory.getConnection()) {
				ValueFactory values = connection.getValueFactory();
				connection.begin();
				for (int patient = 0; patient < PATIENTS; patient++) {
					IRI subject = values.createIRI(EX, "patient" + patient);
					connection.add(subject, RDF.TYPE, values.createIRI(EX, "Patient"));
					for (int encounter = 0; encounter < 3; encounter++) {
						IRI event = values.createIRI(EX, "enc" + patient + "_" + encounter);
						IRI observation = values.createIRI(EX, "obs" + patient + "_" + encounter);
						connection.add(subject, values.createIRI(EX, "hasEncounter"), event);
						connection.add(event, values.createIRI(EX, "hasObservation"), observation);
						connection.add(observation, values.createIRI(EX, "value"),
								values.createLiteral(50 + (patient + encounter) % 30));
						if ((patient * 7 + encounter) % 3 == 0) {
							connection.add(event, values.createIRI(EX, "hasCondition"),
									values.createIRI(EX, "cond" + patient + "_" + encounter));
						}
						if ((patient * 5 + encounter) % 4 == 0) {
							connection.add(event, values.createIRI(EX, "hasCondition"),
									values.createIRI(EX, "cond_flagged"));
						}
					}
				}
				connection.commit();
			}
			return memory;
		} catch (RuntimeException | Error failure) {
			try {
				memory.shutDown();
			} catch (RuntimeException | Error cleanup) {
				if (cleanup != failure) {
					failure.addSuppressed(cleanup);
				}
			}
			throw failure;
		}
	}

	@Test
	void eligibleOptionalUnionKeepsIndependentMemoryAndHandBagsUnderPackedAggregate() {
		String query = "SELECT (COUNT(*) AS ?n) (COUNT(DISTINCT ?patient) AS ?c) WHERE { "
				+ "?patient a <" + EX + "Patient> . ?patient <" + EX + "hasEncounter> ?enc . "
				+ "?enc <" + EX + "hasObservation> ?obs . ?obs <" + EX + "value> ?value . "
				+ "OPTIONAL { { ?enc <" + EX + "hasCondition> ?condition } UNION "
				+ "{ ?enc <" + EX + "hasCondition> ?condition } } }";
		long handRows = 0L;
		for (int patient = 0; patient < PATIENTS; patient++) {
			for (int encounter = 0; encounter < 3; encounter++) {
				long conditions = ((patient * 7 + encounter) % 3 == 0 ? 1L : 0L)
						+ ((patient * 5 + encounter) % 4 == 0 ? 1L : 0L);
				handRows += conditions == 0L ? 1L : 2L * conditions;
			}
		}
		assertThat(handRows).isEqualTo(320L);
		SailRepository memory = independentWitnessMemory();
		try {
			try (SailRepositoryConnection oracle = memory.getConnection();
					SailRepositoryConnection nativeConnection = repository.getConnection()) {
				System.setProperty(PACKED_PROPERTY, "true");
				var independent = oracle.prepareTupleQuery(query);
				SailTupleQuery forced = prepare(nativeConnection, query, PACKED_STRATEGY);
				for (int round = 0; round < 3; round++) {
					List<BindingSet> expected = QueryResults.asList(independent.evaluate());
					assertThat(expected).hasSize(1);
					assertThat(expected.getFirst().getBindingNames()).containsExactlyInAnyOrder("n", "c");
					assertThat(((Literal) expected.getFirst().getValue("n")).longValue()).isEqualTo(handRows);
					assertThat(((Literal) expected.getFirst().getValue("c")).longValue()).isEqualTo(PATIENTS);
					assertThat(QueryResults.asList(forced.evaluate())).containsExactlyElementsOf(expected);
					assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
				}
				Explanation explanation = forced.explain(Explanation.Level.Telemetry);
				assertThat(String.valueOf(explanation))
						.contains("nativeExecutionPath=" + PACKED_STRATEGY)
						.contains("NativeGroup(")
						.doesNotContain("GenericEvalPlan");
				assertThat(AdjacencyIntersectionProbe.ACTIVE_PROBES.get()).isZero();
			}
		} finally {
			memory.shutDown();
		}
	}
